def _snap_truncate(text: str, cap: int, scope: str) -> str:
    if len(text) <= cap:
        return text
    cut = cap
    while cut > 0 and text[cut : cut + 1] != "\n":
        cut -= 1
    if cut == 0:
        cut = cap
    return f"{text[:cut]}\n[TRUNCATED — {scope} exceeded {cap} chars]\n"


